        : command.value[0] == flow.get('CELL_LOCK_STATE') ? flow.get('CELL_LOCK_MAX_DELAY_MS') : undefined;

    flow.get('REQ_CELLS').set(cellDeviceId, command);

    if (typeof timeoutMs == 'number') {
