if (msg.topic == 'cell-set') {
    let state = flow.get('REQ_CELLS').get(cellDeviceId);
    let newState = { ...state, value: msg.payload.value, done: true, timestamp: new Date().getTime() };

    if (state.value[0] == msg.payload.value[0] && !state.done) {
        flow.get('VMLogAlias')('CELL', `Command completed: ${JSON.stringify(newState)}`);
    } else {
        flow.get('VMLogAlias')('CELL', `Unexpected state change: ${JSON.stringify(newState)}`);
    }
    flow.get('REQ_CELLS').set(cellDeviceId, newState);
}

